#include <bits/stdc++.h>
using namespace std;

int n, mod, offset;
int dp[2][1000][2001]; // Adjust size as needed based on constraints

int dp_func(int done, int i, int diff) {
    if (i == n)
        return diff > 0 ? 1 : 0;
    if (dp[done][i][diff + offset] != -1)
        return dp[done][i][diff + offset];
    int rem = n - i;
    int ans = 0;
    for (int l = 0; l < rem; l++) {
        for (int r = (done == 1 ? 0 : l); r < rem; r++) {
            ans += dp_func(done | (l < r ? 1 : 0), i + 1, diff + l - r);
            ans %= mod;
        }
    }
    return dp[done][i][diff + offset] = ans;
}

long long dp2(int i) {
    if (i == n - 1)
        return 0;
    long long ans = (long long)(n - i) * dp2(i + 1);
    ans %= mod;
    for (int l = 0; l < n - i; l++) {
        for (int r = l + 1; r < n - i; r++) {
            ans += dp_func(1, i + 1, l - r);
            ans %= mod;
        }
    }
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> mod;
    offset = n * (n - 1);
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < n; j++)
            for (int k = 0; k < 2 * offset + 1; k++)
                dp[i][j][k] = -1;
    cout << dp2(0) << "\n";
    return 0;
}

